from sklearn.feature_extraction.text import TfidfVectorizer
import re

def task_func(example_str):
    if not isinstance(example_str, str):
        return {}

    # Extract text not enclosed in square brackets
    extracted_text = re.sub(r'\[[^\]]*\]', '', example_str)

    vectorizer = TfidfVectorizer()
    try:
        # Calculate TF-IDF for the extracted text (treated as a single document)
        tfidf_matrix = vectorizer.fit_transform([extracted_text])
        feature_names = vectorizer.get_feature_names_out()
        tfidf_scores = tfidf_matrix.toarray()[0]

        return dict(zip(feature_names, tfidf_scores))
    except ValueError:
        # Raised when the vocabulary is empty (e.g. no valid text left after extraction)
        return {}

